"use strict";(globalThis.webpackChunktemp_docs=globalThis.webpackChunktemp_docs||[]).push([[209],{8902:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"bookSidebar":[{"type":"link","href":"/humanoid-robotics-book/docs/intro","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Module 1: The Robotic Nervous System (ROS 2)","items":[{"type":"link","href":"/humanoid-robotics-book/docs/module1-ros2/intro","label":"What is Physical AI & Why ROS 2 Matters","docId":"module1-ros2/intro","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module1-ros2/architecture","label":"ROS 2 Architecture","docId":"module1-ros2/architecture","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module1-ros2/rclpy","label":"ROS 2 Packages in Python (rclpy)","docId":"module1-ros2/rclpy","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module1-ros2/urdf","label":"URDF for Humanoids","docId":"module1-ros2/urdf","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module1-ros2/mini-project","label":"Mini-Project: Building a Smart Sensor Package","docId":"module1-ros2/mini-project","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module1-ros2/assessment","label":"Module 1 Assessment","docId":"module1-ros2/assessment","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 2: The Digital Twin (Gazebo & Unity)","items":[{"type":"link","href":"/humanoid-robotics-book/docs/module2-digital-twin/intro","label":"Why Robot Simulation Matters","docId":"module2-digital-twin/intro","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module2-digital-twin/gazebo","label":"Setting Up Gazebo + Extensions","docId":"module2-digital-twin/gazebo","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module2-digital-twin/unity","label":"Creating Environments in Unity","docId":"module2-digital-twin/unity","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module2-digital-twin/mini-project","label":"Mini-Project: Building a Custom Gazebo World & Robot Spawn","docId":"module2-digital-twin/mini-project","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module2-digital-twin/assessment","label":"Module 2 Assessment","docId":"module2-digital-twin/assessment","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 3: The AI-Robot Brain (NVIDIA Isaac)","items":[{"type":"link","href":"/humanoid-robotics-book/docs/module3-nvidia-isaac/intro","label":"Isaac Sim Basics","docId":"module3-nvidia-isaac/intro","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module3-nvidia-isaac/isaac-ros","label":"Isaac ROS Pipelines","docId":"module3-nvidia-isaac/isaac-ros","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module3-nvidia-isaac/navigation","label":"VSLAM + Navigation (Nav2)","docId":"module3-nvidia-isaac/navigation","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module3-nvidia-isaac/mini-project","label":"Mini-Project: Synthetic Data Generation & Perception Training (Conceptual)","docId":"module3-nvidia-isaac/mini-project","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module3-nvidia-isaac/assessment","label":"Module 3 Assessment","docId":"module3-nvidia-isaac/assessment","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"category","label":"Module 4: Vision-Language-Action (VLA)","items":[{"type":"link","href":"/humanoid-robotics-book/docs/module4-vla/whisper","label":"Voice-to-Action (Whisper \u2192 Intent)","docId":"module4-vla/whisper","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module4-vla/planners","label":"Natural-language Planners for Robots","docId":"module4-vla/planners","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/module4-vla/assessment","label":"Module 4 Assessment","docId":"module4-vla/assessment","unlisted":false}],"collapsed":true,"collapsible":true},{"type":"link","href":"/humanoid-robotics-book/docs/capstone/","label":"Capstone Project: The Autonomous Humanoid","docId":"capstone/index","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/glossary","label":"Glossary","docId":"glossary","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/references","label":"references","docId":"references","unlisted":false},{"type":"category","label":"Appendices","items":[{"type":"link","href":"/humanoid-robotics-book/docs/appendices/hardware","label":"Hardware Requirements","docId":"appendices/hardware","unlisted":false},{"type":"link","href":"/humanoid-robotics-book/docs/appendices/setup","label":"Software Setup Guide","docId":"appendices/setup","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"appendices/hardware":{"id":"appendices/hardware","title":"Hardware Requirements","description":"This appendix outlines the recommended hardware specifications for effectively engaging with the practical examples and simulations presented in this book. While some theoretical concepts can be understood with minimal hardware, a capable development machine is essential for hands-on experience, especially for NVIDIA Isaac Sim and AI model training.","sidebar":"bookSidebar"},"appendices/setup":{"id":"appendices/setup","title":"Software Setup Guide","description":"This guide provides detailed instructions for setting up your development environment to follow along with the examples and projects in this book. A correctly configured environment is crucial for reproducibility and a smooth learning experience.","sidebar":"bookSidebar"},"capstone/index":{"id":"capstone/index","title":"Capstone Project: The Autonomous Humanoid","description":"This capstone project challenges you to integrate knowledge and skills acquired throughout this book to create an \\"Autonomous Humanoid\\" system. This system will respond to natural language voice commands, plan and execute complex tasks in a simulated environment, identify and manipulate objects, and showcase a complete Vision-Language-Action (VLA) pipeline.","sidebar":"bookSidebar"},"glossary":{"id":"glossary","title":"Glossary","description":"This glossary provides definitions for key terms used throughout the book, particularly those related to Physical AI, Humanoid Robotics, ROS 2, simulation, and Vision-Language-Action (VLA) systems.","sidebar":"bookSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Welcome to the forefront of artificial intelligence and robotics! This book, \\"Physical AI & Humanoid Robotics: From ROS 2 to Vision-Language-Action Systems,\\" is your comprehensive guide to understanding and building intelligent systems that interact with our physical world. As AI moves beyond the confines of data centers and screens, it increasingly finds its embodiment in robots, making the study of Physical AI more crucial than ever.","sidebar":"bookSidebar"},"module1-ros2/architecture":{"id":"module1-ros2/architecture","title":"ROS 2 Architecture","description":"Understanding the architectural components of ROS 2 is crucial for designing, implementing, and debugging robotic applications. ROS 2 provides a modular, distributed, and flexible framework for inter-process communication within a robot system.","sidebar":"bookSidebar"},"module1-ros2/assessment":{"id":"module1-ros2/assessment","title":"Module 1 Assessment","description":"This assessment aims to test your comprehension of the fundamental concepts and practical skills covered in Module 1, focusing on ROS 2 architecture, Python client library (rclpy), and URDF.","sidebar":"bookSidebar"},"module1-ros2/intro":{"id":"module1-ros2/intro","title":"What is Physical AI & Why ROS 2 Matters","description":"Introduction to Physical AI","sidebar":"bookSidebar"},"module1-ros2/mini-project":{"id":"module1-ros2/mini-project","title":"Mini-Project: Building a Smart Sensor Package","description":"This mini-project will guide you through creating a simple ROS 2 Python package that simulates a \\"smart sensor.\\" This sensor will publish temperature readings to a topic, and also respond to a service call to provide its current status.","sidebar":"bookSidebar"},"module1-ros2/rclpy":{"id":"module1-ros2/rclpy","title":"ROS 2 Packages in Python (rclpy)","description":"Python is a popular choice for robotics development due to its readability, extensive libraries, and rapid prototyping capabilities. ROS 2 provides rclpy, a client library that allows you to write ROS 2 nodes in Python, leveraging all the architectural concepts we discussed in the previous chapter.","sidebar":"bookSidebar"},"module1-ros2/urdf":{"id":"module1-ros2/urdf","title":"URDF for Humanoids","description":"The Unified Robot Description Format (URDF) is an XML-based file format used in ROS to describe all aspects of a robot. It\'s crucial for visualizing robots in simulation (e.g., RViz), performing kinematics, dynamics calculations, and interacting with planning and control libraries. For humanoid robots, URDF allows us to precisely define their complex structure, including many links (body parts), various types of joints, and integrated sensors.","sidebar":"bookSidebar"},"module2-digital-twin/assessment":{"id":"module2-digital-twin/assessment","title":"Module 2 Assessment","description":"This assessment aims to test your comprehension of robot simulation principles, your ability to work with Gazebo and Unity, and your understanding of physics and sensor modeling in digital twins.","sidebar":"bookSidebar"},"module2-digital-twin/gazebo":{"id":"module2-digital-twin/gazebo","title":"Setting Up Gazebo + Extensions","description":"Gazebo is a powerful open-source 3D robotics simulator that allows you to accurately and efficiently test your robot algorithms in a virtual environment. This chapter will guide you through installing Gazebo, understanding its core components, and simulating basic robot interactions and sensors.","sidebar":"bookSidebar"},"module2-digital-twin/intro":{"id":"module2-digital-twin/intro","title":"Why Robot Simulation Matters","description":"Robot simulation is an indispensable tool in modern robotics development, offering a safe, efficient, and cost-effective environment to design, test, and refine robotic systems. Before deploying a robot into the real world, developers can leverage digital twins to iterate rapidly, validate algorithms, and mitigate risks.","sidebar":"bookSidebar"},"module2-digital-twin/mini-project":{"id":"module2-digital-twin/mini-project","title":"Mini-Project: Building a Custom Gazebo World & Robot Spawn","description":"This mini-project will guide you through creating a simple, custom Gazebo world and then spawning a robot into it using ROS 2 tools. You\'ll learn how to define static elements, lighting, and use your previously created URDF to populate the environment.","sidebar":"bookSidebar"},"module2-digital-twin/unity":{"id":"module2-digital-twin/unity","title":"Creating Environments in Unity","description":"Unity is a powerful real-time 3D development platform widely used for games, simulations, and interactive experiences. Its strength lies in its intuitive visual editor, high-fidelity rendering capabilities, and extensive asset store. For robotics, Unity allows us to create rich, visually compelling environments and complex human-robot interaction scenes that might be more challenging to achieve in purely robotics-focused simulators like Gazebo.","sidebar":"bookSidebar"},"module3-nvidia-isaac/assessment":{"id":"module3-nvidia-isaac/assessment","title":"Module 3 Assessment","description":"This assessment aims to test your comprehension of NVIDIA Isaac Sim and Isaac ROS, their application in robotics perception and navigation, and your understanding of the sim-to-real transfer paradigm.","sidebar":"bookSidebar"},"module3-nvidia-isaac/intro":{"id":"module3-nvidia-isaac/intro","title":"Isaac Sim Basics","description":"NVIDIA Isaac Sim, built on the Omniverse platform, is a powerful robotics simulation and synthetic data generation tool. It offers highly realistic, physically accurate, and visually rich environments crucial for developing, testing, and training AI-powered robots. Unlike general-purpose simulators, Isaac Sim is specifically designed for robotics, integrating with NVIDIA\'s deep learning tools and accelerating the sim-to-real transfer.","sidebar":"bookSidebar"},"module3-nvidia-isaac/isaac-ros":{"id":"module3-nvidia-isaac/isaac-ros","title":"Isaac ROS Pipelines","description":"NVIDIA Isaac ROS is a collection of hardware-accelerated ROS 2 packages designed to boost the performance of robotic applications. By leveraging NVIDIA GPUs and the underlying CUDA libraries, Isaac ROS significantly speeds up common robotics tasks like perception, navigation, and state estimation, making it ideal for resource-intensive applications such as those involving humanoid robots.","sidebar":"bookSidebar"},"module3-nvidia-isaac/mini-project":{"id":"module3-nvidia-isaac/mini-project","title":"Mini-Project: Synthetic Data Generation & Perception Training (Conceptual)","description":"This mini-project will conceptually guide you through the process of setting up a simple scene in NVIDIA Isaac Sim, generating synthetic data with ground-truth labels, and then outlining how you would use this data to train a basic perception model (e.g., for object detection). Note: The actual training of deep learning models is outside the scope of this mini-project\'s direct execution due to computational requirements, but the workflow is thoroughly explained.","sidebar":"bookSidebar"},"module3-nvidia-isaac/navigation":{"id":"module3-nvidia-isaac/navigation","title":"VSLAM + Navigation (Nav2)","description":"Once a robot can perceive its environment (as enabled by Isaac ROS GEMs), the next crucial step is to enable it to understand where it is (localization), what its surroundings look like (mapping), and how to move from one point to another (path planning and control). This chapter delves into Visual SLAM (VSLAM) for accurate self-localization and introduces the Nav2 stack for robust navigation, with considerations for humanoid robots.","sidebar":"bookSidebar"},"module4-vla/assessment":{"id":"module4-vla/assessment","title":"Module 4 Assessment","description":"This assessment challenges your understanding and practical application of integrating speech recognition, natural language understanding, LLM-based planning, and robot execution to create Vision-Language-Action (VLA) systems.","sidebar":"bookSidebar"},"module4-vla/planners":{"id":"module4-vla/planners","title":"Natural-language Planners for Robots","description":"In the previous chapter, we learned how to extract a structured intent (e.g., \\"pickup blueblock\\") from a human\'s voice command. The next crucial step in creating an intelligent, interactive robot is to translate this high-level intent into a sequence of low-level, executable robot actions. This is the domain of natural language planning, where Large Language Models (LLMs) are proving to be incredibly powerful tools.","sidebar":"bookSidebar"},"module4-vla/whisper":{"id":"module4-vla/whisper","title":"Voice-to-Action (Whisper \u2192 Intent)","description":"One of the most intuitive ways for humans to interact with robots is through natural language, particularly voice commands. This chapter explores how to bridge the gap between spoken language and a robot\'s executable actions, focusing on using OpenAI\'s Whisper for robust speech-to-text conversion and Natural Language Understanding (NLU) techniques to extract actionable intent.","sidebar":"bookSidebar"},"references":{"id":"references","title":"references","description":"","sidebar":"bookSidebar"}}}}')}}]);